-- The valuation guideline (v4.2) as parameter tables, and the switches that
-- correct the Excel workbook's known issues.
--
-- The civil engine (formula civil-2.0.0) reads every rate, factor and list it
-- uses from guideline.* parameters. They are added to every parameter set, old
-- versions included: a valuation dated in the past is calculated with the set
-- then in force, and it needs the tables too. No existing value is changed -
-- ON CONFLICT DO NOTHING leaves any table already published as it is.
--
-- Generated by: node scripts/guideline/build-tables.mjs v4.2 --sql <this file>
-- from docs/guideline/v4.2/reference_tables. Do not edit the JSON by hand.
--
-- Data only: there is no schema change in this migration.

INSERT INTO "valuation_parameters" ("id", "setId", "key", "name", "type", "jsonValue", "discipline", "categoryCode", "notes")
SELECT gen_random_uuid(), s."id", 'guideline.source', 'Guideline release', 'TABLE', '{"version":"v4.2","template":"Version_4.2_Estimation_template","guidelineApproved":"2025-04-23","templateUpdated":"2026-08","reference":"docs/guideline/v4.2/CALCULATION_SPEC.md"}'::jsonb, 'CIVIL', '', 'Guideline v4.2 reference table. Published with the guideline release, not edited by hand.'
FROM "valuation_parameter_sets" s
ON CONFLICT ("setId", "key", "categoryCode") DO NOTHING;

