INSERT INTO "valuation_parameters" ("id", "setId", "key", "name", "type", "jsonValue", "discipline", "categoryCode", "notes")
SELECT gen_random_uuid(), s."id", 'guideline.remarks', 'Standard report remarks', 'TABLE', '{"source":"REMARK!A:D","remarks":[{"section":"I. Cases related to Documentation","case":"When necessary Approved plan are not provided","remark":"Approved Architectural plans are not presented. Actual measurments are taken for this estimation.","impact":"It is possible that constructed buildings without confirmed approval from the concerned government body may be regarded as illegal."},{"section":"I. Cases related to Documentation","case":"When necessary Approved plan are not provided","remark":"Approved Structural Plans are not presented.","impact":"It is possible that constructed or under-construction buildings without confirmed approval from the concerned government body may be structurally unstable, pose safety risks,, and be regarded as illegal."},{"section":"I. Cases related to Documentation","case":"When necessary Approved plan are not provided","remark":"All approved plans are not presented. Actual measurments are taken for this estimation","impact":"It is possible that constructed buildings without confirmed approval from the concerned government body may be regarded as illegal."},{"section":"I. Cases related to Documentation","case":"When provided necessary documents like Plan are not approved","remark":"The presented plans are not approved.","impact":"It is possible that governmental authorization was not granted or the government may not have permitted the presented documents."},{"section":"I. Cases related to Documentation","case":"When Location Map is necessary but not provided","remark":"Location map is not provided","impact":"It may become difficult to the bank in exercising the right to foreclose and transfer of ownership to third party"},{"section":"I. Cases related to Documentation","case":"When the provided Construction Permit is Expired","remark":"The construction permit is expired","impact":"The municipality may take actions such as imposing penalties or other measures if the owner fails to renew the permit on time or does not complete the contract according to schedule."},{"section":"I. Cases related to Documentation","case":"When the Construction Permit is not provided","remark":"The construction permit is not presented","impact":"The owner may not have construction permit at hand. since any construction without prior notice of the concerned organ is illegal, the municipality might take an action (for instance demolishing the improvement)."},{"section":"I. Cases related to Documentation","case":"When the Professional License is not provided","remark":"Professional license is not attached.","impact":"The BOQ might not be prepared by qualified personnel or the person who prepared the BOQ is not known and doesn’t give assurance that the BOQ is prepared according to the approved plan."},{"section":"I. Cases related to Documentation","case":"When the presented Professional License is expired.","remark":"The provided professional license is expired.","impact":"The BOQ might not be prepared by qualified personnel or the person who prepared the BOQ is not known and doesn’t give assurance that the BOQ is prepared according to the approved plan."},{"section":"I. Cases related to Documentation","case":"When the consultant firm License is not provided","remark":"Consultant firm license is not attached.","impact":"The BOQ might not be prepared by qualified consultant firm who prepared the BOQ is not known and doesn’t give assurance that the BOQ is prepared according to the approved plan."},{"section":"I. Cases related to Documentation","case":"When the presented consultant firm License is expired.","remark":"The provided consultant firm license is expired.","impact":"The BOQ might not be prepared by qualified consultant firm who prepared the BOQ is not known and doesn’t give assurance that the BOQ is prepared according to the approved plan."},{"section":"I. Cases related to Documentation","case":"When Commitment form to be filled by the applican is Incomplete or not provided","remark":"Commitment form filled by the Applicant is not presented","impact":"The applicant may not commit to do the construction as per the BOQ"},{"section":"I. Cases related to Documentation","case":"When Commitment form to be filled by the Professional is Incomplete or not provided","remark":"Commitment form filled by the professional is not presented","impact":"The professional may not take responsibility to the presented BOQ"},{"section":"I. Cases related to Documentation","case":"When Land Tax Payment Receipt is not provided","remark":"Current land tax payment receipt is not attached.","impact":"The owner may not have paid the tax payments on schedule. Consequently, the concerned organ may take action according to the law."},{"section":"I. Cases related to Documentation","case":"When Lease agreement is not provided","remark":"Location value is calculated by using the assumption of the guideline since the lease agreement is not provided.","impact":"The location value is affected by lease terms that may lead to a significant location value change."},{"section":"I. Cases related to Documentation","case":"When Lease Payment Receipt is not provided","remark":"Lease payment receipt is not attached.","impact":"The owner may not have paid the lease payments on schedule. Consequently, the concerned organ may take action according to contractual (lease) agreement."},{"section":"I. Cases related to Documentation","case":"When no document is presented for the fuel tankers","remark":"No documentation provided for tankers age, we were unable to verify their condition or depreciation status.","impact":"The Remarks Indicate Limitations In Verifying The Tankers’ Condition. If Buried And Undocumented, Their State Cannot Be Assessed. Even With Documents, Burial Over 25 Years Ago Suggests Possible Deterioration That May Affect Their Value."},{"section":"I. Cases related to Documentation","case":"When a document is presented but the fuel tankers are over 25 old","remark":"The tankers are 25 years old, and their condition may have significantly deteriorated, impacting their value.","impact":null},{"section":"II. Cases related to LHC","case":"Construction outside the boundaries of the LHC","remark":"The existing/actual building is constructed _____% outside from the presented Land Holding Certificate (LHC).","impact":"It may become challenging for the bank to exercise its right to foreclose and transfer ownership to a third party The Municipality may choose to demolish any part of the building that was constructed beyond the approved boundaries at any time In the event of a dispute with a neighboring owner, the portion of the property that extends beyond the plot may be required to be demolished The portion of the building that was demolished (outside the LHC) may impact the structural integrity of the entire building"},{"section":"II. Cases related to LHC","case":"Incomplete Title Deed Number","remark":"LHC has no title deed number","impact":"This type of LHC may not be uniquely recognized and registered."},{"section":"II. Cases related to LHC","case":"Unclear Title Deed Number","remark":"The tittle deed number of the LHC is not Visible or not clearly written, hence better to check from concerned organ","impact":"There might be difficulty in registering the plot."},{"section":"II. Cases related to LHC","case":"Temporary LHC","remark":"The presented LHC is temporary","impact":"The municipality might take action on the plot, if the owner doesn’t fulfill its commitment according to lease agreement or construction permit or according to any other contractual documents."},{"section":"II. Cases related to LHC","case":"Rural Land Administration Issued LHC","remark":"The land holding certificate is issued by the rural land administration and contains only reference number but not land holding number.","impact":"There might be difficulty in registering the plot."},{"section":"II. Cases related to LHC","case":"Proportional LHC","remark":"The presented LHC is proportional","impact":"It may create difficulty for the bank when transferring ownership to a third party and in exercising the right to foreclose."},{"section":"II. Cases related to LHC","case":"Cooperative Land Holding Ceritficates","remark":"Letter of consent from members is not attached","impact":"Pursuit to cooperative society proclamation No 147/91 the share of benefit of a member in the society shall not be liable to attachment or sale except for the debt due to the society"},{"section":"II. Cases related to LHC","case":null,"remark":"Specific plot of the owner is not identified on the LHC by the cooperative''s executive members.","impact":"Plots and buildings within a cooperative housing scheme often resemble one another. Therefore, unless explicitly specified, an incorrect premise might be used for valuation."},{"section":"II. Cases related to LHC","case":"Mismatching Plot Area in the LHC and the Lease Agreement","remark":"The Plot area on the LHC is different from that stated on lease agreement .Uses the lesser area to the estimation process.","impact":"It is difficult to determine which one is the exact area of the plot. Hence it may become encumbrance to the bank in transfer of ownership to the third party and in exercising the right to foreclose."},{"section":"II. Cases related to LHC","case":"Land Uses Different from the Permited Land Use by the Authorities","remark":"Plot used for _____, permitted for _____. Report uses _____ purpose.","impact":"The municipality might take action on the plot since the owner doesn’t use the plot for the intended purpose."},{"section":"II. Cases related to LHC","case":"Remaining Lease Period (if it is short period of time)","remark":"The remaining lease period is ______ years.","impact":"The owner may lose ownership before settling the loan."},{"section":"II. Cases related to LHC","case":"Discrepancy in plot area between the LHC and coordinate calculations.","remark":"The area stated on the Land Holding Certificate (LHC) does not correspond with the coordinated area; however, a smaller area used for the estimation.","impact":"It may become difficult to the bank in exercising the right to foreclose and transfer of ownership to third party"},{"section":"II. Cases related to LHC","case":"Discrepancy in owner names between the Land Holding Certificate (LHC) and the approved plans, (If legal documents are not attached which approved by the responsible organs, example sales agreements with the full history)","remark":"The Owner name on presented approved plan is different from owner name on presented LHC or on presented lease agreement or on presented payment receipt.","impact":"The customer may present similar approved plan of other property owner, which in this case the actual building may not have approved plan and the consequence is similar to remark No. 2. Unless, legal documents shall be checked beforehand"},{"section":"II. Cases related to LHC","case":"Plots with a smaller plot area than the LHC''s stated area","remark":"Plot area reduced by ______% from LHC; location value based on reduced area.","impact":"It might become difficult to the bank in exercising the right to foreclose and transfer of ownership to third party."},{"section":"III. Cases related to Plan and actual consrtuction","case":"Properties enlarged above the specifications of the approved plan","remark":"The existing/actual building area is enlarged by_____% from the presented approved plan.","impact":"It may have consequential damage on the building & compensation might not be paid for such enlarged properties."},{"section":"III. Cases related to Plan and actual consrtuction","case":"Properties enlarged above the specifications of the approved plan","remark":"The existing/actual Factory/Ware House/MPH building volume is enlarged by_____% from the presented approved plan.","impact":"It may have consequential damage on the building & compensation might not be paid for such enlarged properties."},{"section":"III. Cases related to Plan and actual consrtuction","case":"Properties that have been reduced compared to the specifications of the authorized plan","remark":"The existing/actual building is reduced by_____% from the approved plan.","impact":"It may not have substantial effect just for information."},{"section":"III. Cases related to Plan and actual consrtuction","case":"Properties that have been reduced compared to the specifications of the authorized plan","remark":"The existing/actual Factory/Ware House/Multi Purpose Hall building volume is reduced by_____% from the presented approved plan.","impact":"It may not have substantial effect just for information."},{"section":"III. Cases related to Plan and actual consrtuction","case":"Plots that will be reduced as a result of road expansion in the future","remark":"LHC area is reduced by ____% due to road expansion; location value uses reduced area.","impact":"Part of plot reserved for road development scheme by the government may be taken at any time by compensating for approved constructions only there by affecting the location value and those constructions that will be remarked."},{"section":"III. Cases related to Plan and actual consrtuction","case":"Discrepancies between the actual and approved plans regarding the number of stories.","remark":"Permitted approved building is for________________stories but the constructed/existing building is ________________stories.","impact":"Buildings constructed without prior approval of the concerned government body are considered as illegal . It may not be structurally stable"},{"section":"III. Cases related to Plan and actual consrtuction","case":"Demolished portion of a Building","remark":"____% of the building''s structure has been demolished.","impact":"It may not be structurally stable"},{"section":"III. Cases related to Plan and actual consrtuction","case":"Unconstructed Buildings listed in the approved Plan (If the property is to be held for collateral not project financing by the bank)","remark":"As per the presented approved site plan there are _____blocks in the compound but constructed ______blocks in the compound.","impact":"Since the owner doesn’t fulfill his/her commitment accordingly, the municipality might take the whole or partial of the plot at any time. If the owner doesn’t fulfill his/her commitment accordingly, there might be difficulty in case of transferring to the third party The remaining buildings which are not constructed yet might be necessary for the intended business on the plot The remaining buildings may have effect on the ongoing business"},{"section":"III. Cases related to Plan and actual consrtuction","case":"Building that do not Satisfy the Minimum Requirement for a Property to be held as Collateral","remark":"The ______________ building is not included in the valuation since it does not fulfill the minimum requirement to be held as collateral.","impact":"It is to inform that there is building in the compound which is not included in the estimation but will or may be included if the owner upgrades the building for the future during re estimation."},{"section":"III. Cases related to Plan and actual consrtuction","case":"Discrepancies among the Land Holding Certificate (LHC), lease agreement, and construction permit.","remark":"The LHC and/or lease agreement and/or construction permit is not confirmed against the original","impact":"It is not known whether the original documents are observed or not by any authorized bank staff."},{"section":"III. Cases related to Plan and actual consrtuction","case":"Orientation (Northing) Problem (if tilted slightly - to 70 degree)","remark":"LHC shows slightly tilted northing","impact":"It is recommended to check exact plot of the owner"},{"section":"III. Cases related to Plan and actual consrtuction","case":"Orientation (Northing) Problem (If tilted more than 70 degree","remark":"The orientation (Northing) on the presented Land Holding Certificate differs from the actual orientation.","impact":"It is challenging to determine the exact plot of the customer. Hence it may become difficult to the bank in transfer of ownership to the third party and in exercising the right to foreclose."},{"section":"III. Cases related to Plan and actual consrtuction","case":"Underconstruction Building Estimation as Collateral","remark":"The building is under construction, but only the executed amount is estimated for collateral purposes.","impact":"It may not have substantial effect just for information."},{"section":"III. Cases related to Plan and actual consrtuction","case":"LHC is MIXED USE","remark":"The Land Holding Certificate (LHC) was designated \"mixed-use\"; however, this valuation reflects the property’s current state, which is ____________________.","impact":"This means that the Land Holding Certificate (LHC) originally labeled the property as \"mixed-use,\" but the valuation is based on what the property is actually like now"},{"section":"III. Cases related to Plan and actual consrtuction","case":"If the ground floor is changed to walkway with the corridor development","remark":"Ground floor is currently changed to walking way.","impact":"This means that the Ground floor area is not functioning as per the blueprint."},{"section":"III. Cases related to Plan and actual consrtuction","case":"If some of the area is demolished, or will be demolished with corridor development.","remark":"The property is subjected to Corridor development","impact":"This means that, some areas of the building will be out of the function presented on blue print."},{"section":"III. Cases related to Plan and actual consrtuction","case":"If there is Lift on actual project but not included on the BOQ","remark":"Lift work is included in the estimation with minimum replacement rate.","impact":"Since, the lift installation work is already executed on the project, eventhough it is not on BOQ, it is included in the estimation."},{"section":"III. Cases related to Plan and actual consrtuction","case":"If there Shoring work is presented with all supplimentary documents","remark":"_______________________________Amount of shoring work is executed which is not included in this estimation report.","impact":"This means that, shoring work is executed by the customer as additional safety but the amount is not included in the estimation."},{"section":"III. Cases related to Plan and actual consrtuction","case":"Re estimation before three years","remark":"This re-estimation is done prior to three years from the previous one as per the request with the new property valuation guideline.","impact":"It may not have substantial effect just for information."},{"section":"III. Cases related to Plan and actual consrtuction","case":"when BOQ is not provided","remark":"Due to the lack of a Bill of Quantities, cost estimates are based on standard guidelines. Any changes to finishing materials during construction may alter the total project cost amount.","impact":"In the absence of a Bill of Quantities, our cost assumptions have been derived based on the applicable guidelines for the remaining scope of work. It should be noted that any modifications to the specified finishing materials during the construction phase may result in variations to the overall project cost, either upward or downward."}]}'::jsonb, 'CIVIL', '', 'Guideline v4.2 reference table. Published with the guideline release, not edited by hand.'
FROM "valuation_parameter_sets" s
ON CONFLICT ("setId", "key", "categoryCode") DO NOTHING;

INSERT INTO "valuation_parameters" ("id", "setId", "key", "name", "type", "jsonValue", "discipline", "categoryCode", "notes")
SELECT gen_random_uuid(), s."id", 'excel_fixes.switches', 'Corrections to the Excel workbook', 'TABLE', '{"neighbourhoodExactMatch":false,"industrialBarThresholds":false,"multiStoreyDefectRates":false,"bothHoldingDoubleCount":false,"addisTierFormula":false,"progressLocationValue":false}'::jsonb, 'CIVIL', '', 'Each switch corrects one known issue in the Excel estimation template (docs/guideline/v4.2/CALCULATION_SPEC.md, section 11). All are off, so figures match the workbook; switch one on only once the valuation unit has approved it.'
FROM "valuation_parameter_sets" s
ON CONFLICT ("setId", "key", "categoryCode") DO NOTHING;

-- Parameters the guideline engine no longer reads keep their values, with a
-- note saying what replaced them.

UPDATE "valuation_parameters" SET "notes" = 'No longer read: the civil engine takes the market condition factor for the city and land purpose from the guideline table guideline.cities.' WHERE "key" = 'cost_approach.mcf';
UPDATE "valuation_parameters" SET "notes" = 'No longer read: the civil engine values lease-held land by the guideline rule (guideline.location_value).' WHERE "key" = 'land.lease_valuation_basis';
UPDATE "valuation_parameters" SET "notes" = 'No longer read: the civil engine depreciates a building by its recorded condition defects (guideline.condition_defects). Mechanical items use mechanical.economic_life.' WHERE "key" = 'depreciation.economic_life';
UPDATE "valuation_parameters" SET "notes" = 'No longer read: a building under construction is valued from the completion of each of its components.' WHERE "key" = 'construction.element_weights';
